var s={local:{nombre:"Real Madrid",abreviatura:"RMA",escudo:"https://thumb.wikimedia.org/wikipedia/en/thumb/5/56/Real_Madrid_CF.svg/330px-Real_Madrid_CF.svg.png"},visitante:{nombre:"Atl\xE9tico de Madrid",abreviatura:"ATM",escudo:"https://thumb.wikimedia.org/wikipedia/en/thumb/f/f9/Atletico_Madrid_Logo_2024.svg/330px-Atletico_Madrid_Logo_2024.svg.png"},competicion:"LaLiga EA Sports",jornada:"Jornada 16 \xB7 Derbi madrile\xF1o",estadio:"Estadio Metropolitano",ciudad:"Madrid",fecha:"2026-12-13T21:00:00+01:00",zonaHoraria:"+0100",imagenEstadio:"https://www.socios.com/wp-content/uploads/2026/05/civitas-metropolitano.jpg"};var r=["1. La entrada da derecho a acceder a un \xFAnico partido, en la fecha, hora y asiento indicados. No es v\xE1lida para partidos aplazados a otra sede salvo comunicaci\xF3n oficial del organizador.","2. El acceso se realiza exclusivamente con el c\xF3digo QR digital asociado a la compra. Cada c\xF3digo se valida una sola vez; las capturas de pantalla, copias o reventas no autorizadas pueden ser anuladas sin derecho a reembolso.","3. Las puertas del estadio se abren dos (2) horas antes del inicio del partido. El organizador no garantiza el acceso de los espectadores que lleguen una vez iniciada la primera parte.","4. Est\xE1 prohibido introducir armas, objetos punzantes, bengalas, petardos, bebidas alcoh\xF3licas, sustancias estupefacientes, paraguas, cascos, cadenas y cualquier objeto que pueda usarse como proyectil.","5. Todo espectador est\xE1 sujeto a registro por parte del personal de seguridad y de la Polic\xEDa Nacional. Negarse al registro implica la p\xE9rdida del derecho de acceso sin reembolso del importe pagado.","6. El espectador autoriza el uso de su imagen captada durante el partido en retransmisiones de televisi\xF3n, plataformas digitales y material promocional del organizador, sin que ello genere contraprestaci\xF3n alguna.","7. Las entradas no admiten cambios ni devoluciones, salvo en caso de suspensi\xF3n definitiva del partido. En ese caso se reembolsar\xE1 el importe de la entrada, sin incluir los gastos de gesti\xF3n, en un plazo de treinta (30) d\xEDas h\xE1biles.","8. Los menores de catorce (14) a\xF1os deben acceder acompa\xF1ados por un adulto responsable y contar con su propia entrada. Por motivos de seguridad no se permite el acceso de menores de cinco (5) a\xF1os.","9. El espectador debe ocupar \xFAnicamente el asiento indicado en su entrada. El personal de seguridad podr\xE1 reubicar o desalojar a quien ocupe un asiento distinto o permanezca en escaleras y v\xEDas de evacuaci\xF3n.","10. Las conductas violentas, racistas, xen\xF3fobas o intolerantes dar\xE1n lugar a la expulsi\xF3n inmediata del estadio y a las sanciones previstas en la Ley 19/2007, contra la violencia, el racismo, la xenofobia y la intolerancia en el deporte."];function a(...e){return[...r,...e].join(`

`)}var n=[{id:"PALCO",nombre:"Palco",descripcion:"Zona privada en el anfiteatro del lateral oeste, con la mejor vista panor\xE1mica del terreno de juego.",precio:450,color:"#4a3aa7",beneficios:["Acceso por puerta exclusiva sin colas","Catering y bebidas durante todo el partido","Asiento acolchado con reposabrazos","Plaza de aparcamiento cubierta incluida","Bufanda oficial de regalo"],terminosYCondiciones:a("11. El servicio de catering comienza dos (2) horas antes del partido y finaliza al terminar la segunda parte. Las bebidas alcoh\xF3licas solo se sirven a mayores de edad dentro del palco.","12. La plaza de aparcamiento incluida est\xE1 sujeta a disponibilidad y se asigna por orden de llegada. El veh\xEDculo debe retirarse como m\xE1ximo una (1) hora despu\xE9s de finalizado el partido.")},{id:"VIP",nombre:"VIP",descripcion:"Primeras filas del lateral oeste, en el centro del campo y a pie de c\xE9sped.",precio:280,color:"#eda100",beneficios:["Acceso preferente por la puerta 1","Zona lounge con comida y bebida","Asiento acolchado numerado","Bufanda oficial de regalo"],terminosYCondiciones:a("11. El acceso a la zona lounge requiere la pulsera entregada en la puerta 1. La pulsera es personal e intransferible y su p\xE9rdida no da derecho a reposici\xF3n.")},{id:"PREFERENCIAL",nombre:"Preferencia",descripcion:"Grada baja central del lateral este, frente a las c\xE1maras de televisi\xF3n y a los banquillos.",precio:160,color:"#e34948",beneficios:["Acceso por la puerta 5 con colas reducidas","Asiento numerado con respaldo","Zona de restauraci\xF3n exclusiva de la grada"],terminosYCondiciones:a("11. La zona de restauraci\xF3n exclusiva funciona hasta el final del descanso. Los precios de la comida y la bebida no est\xE1n incluidos en la entrada.")},{id:"OCCIDENTAL",nombre:"Lateral Oeste",descripcion:"Grada lateral oeste, bajo la cubierta que protege de la lluvia y del sol.",precio:110,color:"#2a78d6",beneficios:["Asiento numerado","Grada cubierta","Videomarcador frente a la grada"],terminosYCondiciones:a()},{id:"ORIENTAL",nombre:"Lateral Este",descripcion:"Grada lateral este, con vista completa del terreno de juego desde el costado.",precio:90,color:"#1baf7a",beneficios:["Asiento numerado","Vista lateral de todo el campo"],terminosYCondiciones:a()},{id:"GENERAL",nombre:"Fondo",descripcion:"Fondos norte y sur, detr\xE1s de las porter\xEDas. El ambiente m\xE1s animado del estadio.",precio:55,color:"#eb6834",beneficios:["Asiento numerado","Ambiente de animaci\xF3n detr\xE1s de la porter\xEDa"],terminosYCondiciones:a("11. En los fondos solo se permite el acceso de banderas sin m\xE1stil y de instrumentos musicales autorizados previamente por el organizador.")}];function t(e){let o=n.find(i=>i.id===e);if(!o)throw new Error(`La localidad "${e}" no existe en la base de datos.`);return o}var c={DISPONIBLE:"Disponible",RESERVADA:"Reservado",VENDIDA:"Vendido"},p={DISPONIBLE:"\u25CF",RESERVADA:"\u25D0",VENDIDA:"\u25CB"},u={ORIENTAL:"Lateral Este",SUR:"Fondo Sur",OCCIDENTAL:"Lateral Oeste",NORTE:"Fondo Norte"};function m(e,o){return e===o?e:`${e} \xB7 ${o}`}export{s as a,n as b,t as c,c as d,p as e,u as f,m as g};
